<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();
if(isset($_GET['discharge'])){$id=(int)$_GET['discharge'];$pdo->beginTransaction();$s=$pdo->prepare('SELECT bed_id FROM admissions WHERE id=? AND status="Admitted" FOR UPDATE');$s->execute([$id]);$a=$s->fetch();if($a){$pdo->prepare('UPDATE admissions SET status="Discharged",discharged_at=NOW() WHERE id=?')->execute([$id]);if($a['bed_id'])$pdo->prepare('UPDATE beds SET status="Available" WHERE id=?')->execute([$a['bed_id']]);} $pdo->commit();audit('discharge','admission',$id);flash('Patient discharged and bed released.');redirect('admissions.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->beginTransaction();$bed=($_POST['bed_id']??'')?:null;$no='ADM-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(2)));$s=$pdo->prepare('INSERT INTO admissions(patient_id,bed_id,admission_no,reason,diagnosis,status) VALUES(?,?,?,?,?,"Admitted")');$s->execute([(int)$_POST['patient_id'],$bed,$no,trim($_POST['reason']??''),trim($_POST['diagnosis']??'')]);if($bed)$pdo->prepare('UPDATE beds SET status="Occupied" WHERE id=? AND status="Available"')->execute([(int)$bed]);$pdo->commit();audit('admit','admission',(int)$pdo->lastInsertId(),$no);flash('Admission created: '.$no);redirect('admissions.php');}
$patients=$pdo->query('SELECT id,patient_no,full_name FROM patients ORDER BY full_name')->fetchAll();$beds=$pdo->query("SELECT b.id,b.bed_no,w.name ward FROM beds b JOIN wards w ON w.id=b.ward_id WHERE b.status='Available' ORDER BY w.name,b.bed_no")->fetchAll();$rows=$pdo->query('SELECT a.*,p.patient_no,p.full_name,b.bed_no,w.name ward FROM admissions a JOIN patients p ON p.id=a.patient_id LEFT JOIN beds b ON b.id=a.bed_id LEFT JOIN wards w ON w.id=b.ward_id ORDER BY a.admitted_at DESC')->fetchAll();admin_header('Admissions','admissions.php');?><div class="pagehead"><div><h1>Admissions</h1><div class="muted">Inpatient admission, bed allocation and discharge.</div></div><a class="btn" href="?action=new">Admit patient</a></div><?php if(($_GET['action']??'')==='new'):?><div class="card" style="margin-bottom:18px"><h2>New admission</h2><form method="post"><?=csrf_field()?><div class="form-grid"><div class="field"><label>Patient</label><select name="patient_id" required><option value="">Select patient</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=e($p['patient_no'].' — '.$p['full_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Available bed</label><select name="bed_id"><option value="">No bed assigned yet</option><?php foreach($beds as $b):?><option value="<?=$b['id']?>"><?=e($b['ward'].' — Bed '.$b['bed_no'])?></option><?php endforeach;?></select></div><div class="field full"><label>Reason</label><textarea name="reason"></textarea></div><div class="field full"><label>Working diagnosis</label><textarea name="diagnosis"></textarea></div></div><button style="margin-top:14px">Admit patient</button></form></div><?php endif;?><div class="card table-wrap"><table class="table"><tr><th>Admission No.</th><th>Patient</th><th>Ward/Bed</th><th>Admitted</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['admission_no'])?></td><td><?=e($r['patient_no'].' — '.$r['full_name'])?></td><td><?=e(($r['ward']??'Unassigned').' / '.($r['bed_no']??'—'))?></td><td><?=e($r['admitted_at'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='Admitted'):?><a class="btn secondary" href="?discharge=<?=$r['id']?>">Discharge</a><?php else:?><?=e($r['discharged_at'])?><?php endif;?></td></tr><?php endforeach;?></table></div><?php admin_footer();
